package cn.zhuatech.itsm.deep;import cn.zhuatech.itsm.common.ApiResponse;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/itsm-ops") public class DeepItsmController{private final DeepItsmService s;public DeepItsmController(DeepItsmService x){s=x;}@GetMapping("/workspace")ApiResponse<?> workspace(){return ApiResponse.ok(s.workspace());}@PostMapping("/incidents")ApiResponse<?> incident(@RequestBody DeepItsmService.IncidentInput x){return ApiResponse.ok(s.incident(x));}@PostMapping("/incidents/{id}/assign")ApiResponse<?> assign(@PathVariable Long id,@RequestBody DeepItsmService.AssignInput x){return ApiResponse.ok(s.assign(id,x));}@PostMapping("/incidents/{id}/resolve")ApiResponse<?> resolve(@PathVariable Long id,@RequestBody DeepItsmService.ResolveInput x){return ApiResponse.ok(s.resolve(id,x));}@PostMapping("/incidents/{id}/close")ApiResponse<?> close(@PathVariable Long id){return ApiResponse.ok(s.closeIncident(id));}@PostMapping("/problems")ApiResponse<?> problem(@RequestBody DeepItsmService.ProblemInput x){return ApiResponse.ok(s.problem(x));}@PostMapping("/changes")ApiResponse<?> change(@RequestBody DeepItsmService.ChangeInput x){return ApiResponse.ok(s.change(x));}@PostMapping("/changes/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submitChange(id));}}
